namespace sv_f48e9de4ebad459591c2680a1b0f36c4.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@inherits LayoutComponentBase

<div class="chat-layout">
    @Body
</div>

.chat-layout {
    height: 100vh;
    overflow: hidden;
}

@using sv_f48e9de4ebad459591c2680a1b0f36c4.Services

<div class="channel-item @(IsActive ? "active" : "")" @onclick="OnSelected">
    <div class="channel-info">
        <span class="channel-name"># @Channel.Name</span>
        <span class="channel-description">@Channel.Description</span>
    </div>
    @if (Channel.UnreadCount > 0)
    {
        <span class="badge bg-primary unread-badge">@Channel.UnreadCount</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback OnSelected { get; set; }
}

.channel-item {
    padding: 6px 16px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background-color: #393c43;
}

.channel-item.active {
    background-color: #42464d;
}

.channel-info {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.channel-name {
    font-weight: 500;
    white-space: nowrap;
}

.channel-description {
    font-size: 0.78em;
    color: #8e9297;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.unread-badge {
    flex-shrink: 0;
    font-size: 0.72em;
    border-radius: 10px;
    min-width: 20px;
    text-align: center;
}

@using sv_f48e9de4ebad459591c2680a1b0f36c4.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h5>Channels</h5>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == SelectedChannelId"
                         OnSelected="() => OnChannelSelected.InvokeAsync(channel.Id)" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

.channel-sidebar {
    flex: 0 0 20%;
    background-color: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border-right: 1px solid #23272a;
}

.sidebar-header {
    padding: 14px 16px;
    border-bottom: 1px solid #23272a;
}

.sidebar-header h5 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
    padding: 8px 0;
}

.message-input {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #2c2f33;
    flex-shrink: 0;
    align-items: flex-end;
}

.message-input textarea {
    flex: 1;
    background-color: #40444b;
    border: none;
    border-radius: 6px;
    padding: 8px 12px;
    color: #dcddde;
    resize: none;
    font-family: inherit;
    font-size: 0.9em;
    line-height: 1.4;
}

.message-input textarea::placeholder {
    color: #72767d;
}

.message-input textarea:focus {
    outline: none;
    box-shadow: 0 0 0 1px #7289da;
}

@using sv_f48e9de4ebad459591c2680a1b0f36c4.Services

<div class="message-bubble"
     @onmouseenter="() => showActions = true"
     @onmouseleave="HideOverlays">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="reaction-bar">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="reaction-badge"
                        @onclick="() => OnReact.InvokeAsync((Message.Id, reaction.Emoji))">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (ThreadSummary is not null)
    {
        <button class="thread-link" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            💬 @ThreadSummary.ReplyCount @(ThreadSummary.ReplyCount == 1 ? "reply" : "replies")
        </button>
    }

    @if (showActions)
    {
        <div class="message-actions">
            <button class="action-btn" title="Reply in thread"
                    @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">💬</button>
            <button class="action-btn" title="Add reaction"
                    @onclick="ToggleEmojiPicker">😀</button>
        </div>
    }

    @if (showEmojiPicker)
    {
        <div class="emoji-picker">
            @foreach (var emoji in CommonEmojis)
            {
                <button @onclick="() => SelectEmoji(emoji)">@emoji</button>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public ThreadSummary? ThreadSummary { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private bool showActions;
    private bool showEmojiPicker;

    private static readonly string[] CommonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    private void HideOverlays()
    {
        showActions = false;
        showEmojiPicker = false;
    }

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task SelectEmoji(string emoji)
    {
        showEmojiPicker = false;
        showActions = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        return diff switch
        {
            { TotalSeconds: < 60 } => "just now",
            { TotalMinutes: < 60 } => $"{(int)diff.TotalMinutes} min ago",
            { TotalHours: < 24 } => $"{(int)diff.TotalHours}h ago",
            { TotalDays: < 7 } => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }
}

.message-bubble {
    position: relative;
    padding: 6px 12px;
    border-radius: 4px;
    margin-bottom: 2px;
    transition: background-color 0.1s;
}

.message-bubble:hover {
    background-color: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9em;
}

.message-time {
    font-size: 0.72em;
    color: #72767d;
}

.message-content {
    line-height: 1.4;
    font-size: 0.9em;
    word-break: break-word;
}

.reaction-bar {
    display: flex;
    gap: 4px;
    margin-top: 4px;
    flex-wrap: wrap;
}

.reaction-badge {
    background-color: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 6px;
    padding: 1px 6px;
    font-size: 0.82em;
    cursor: pointer;
    color: #dcddde;
    line-height: 1.6;
}

.reaction-badge:hover {
    border-color: #7289da;
    background-color: rgba(114, 137, 218, 0.1);
}

.thread-link {
    background: none;
    border: none;
    color: #7289da;
    font-size: 0.8em;
    padding: 4px 0 0;
    cursor: pointer;
    display: block;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 8px;
    display: flex;
    gap: 1px;
    background-color: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px;
    z-index: 5;
}

.action-btn {
    background: none;
    border: none;
    padding: 2px 8px;
    cursor: pointer;
    border-radius: 3px;
    font-size: 0.95em;
    line-height: 1.4;
}

.action-btn:hover {
    background-color: #4f545c;
}

.emoji-picker {
    position: absolute;
    top: -12px;
    right: 90px;
    background-color: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 6px;
    padding: 4px;
    display: flex;
    gap: 2px;
    z-index: 10;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.emoji-picker button {
    background: none;
    border: none;
    padding: 4px 6px;
    cursor: pointer;
    font-size: 1.15em;
    border-radius: 3px;
    line-height: 1;
}

.emoji-picker button:hover {
    background-color: #4f545c;
}

