{"path": "/tmp/sv-f48e9de4ebad459591c2680a1b0f36c4/Components/Chat/MessageInput.razor", "file_text": "<div class="message-input">
    <textarea @bind="inputText" @bind:event="oninput"
              @onkeydown="HandleKeyDown"
              placeholder="@Placeholder"
              rows="2"></textarea>
    <button class="btn btn-primary btn-sm" @onclick="HandleSubmit"
            disabled="@string.IsNullOrWhiteSpace(inputText)">
        @ButtonText
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message...";
    [Parameter] public string ButtonText { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSubmit { get; set; }

    private string inputText = "";

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey && !string.IsNullOrWhiteSpace(inputText))
        {
            await HandleSubmit();
        }
    }

    private async Task HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(inputText)) return;
        var text = inputText.Trim();
        inputText = "";
        await OnSubmit.InvokeAsync(text);
    }
}
"}

