.message-bubble {
    position: relative;
    padding: 6px 12px;
    border-radius: 4px;
    margin-bottom: 2px;
    transition: background-color 0.1s;
}

.message-bubble:hover {
    background-color: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
