    border-radius: 6px;
    padding: 1px 6px;
    font-size: 0.82em;
    cursor: pointer;
    color: #dcddde;
    line-height: 1.6;
}

.reaction-badge:hover {
    border-color: #7289da;
    background-color: rgba(114, 137, 218, 0.1);
}

.thread-link {
    background: none;
    border: none;
    color: #7289da;
    font-size: 0.8em;
    padding: 4px 0 0;
    cursor: pointer;
    display: block;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 8px;
    display: flex;
    gap: 1px;
    background-color: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px;
    z-index: 5;
}

.action-btn {
    background: none;
    border: none;
    padding: 2px 8px;
    cursor: pointer;
    border-radius: 3px;
