.emoji-picker button {
    background: none;
    border: none;
    padding: 4px 6px;
    cursor: pointer;
    font-size: 1.15em;
    border-radius: 3px;
    line-height: 1;
}

.emoji-picker button:hover {
    background-color: #4f545c;
}

