@using sv_f48e9de4ebad459591c2680a1b0f36c4.Services
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-area">
    <div class="message-area-header">
        <h4># @ChannelName</h4>
        <p>@ChannelDescription</p>
    </div>
    <div class="message-list" @ref="messageListRef">
        @if (HasMoreMessages)
        {
            <div class="load-more">
                <button class="btn btn-sm btn-outline-secondary" @onclick="OnLoadMore"
                        disabled="@IsLoading">
                    @(IsLoading ? "Loading…" : "Load older messages")
                </button>
            </div>
        }
        @foreach (var message in Messages)
        {
            <MessageBubble Message="message"
                           ThreadSummary="ThreadSummaries.GetValueOrDefault(message.Id)"
                           OnOpenThread="OnOpenThread"
                           OnReact="OnReact" />
        }
    </div>
    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonText="Send"
                  OnSubmit="HandleSend" />
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public bool IsLoading { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference messageListRef;
    private IJSObjectReference? jsModule;
    private DotNetObjectReference<MessageArea>? dotNetRef;
    private bool shouldScrollToBottom;
    private int previousMessageCount;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-f48e9de4ebad459591c2680a1b0f36c4/Components/Chat/MessageArea.razor.js");
            await jsModule.InvokeVoidAsync("registerScrollHandler", messageListRef, dotNetRef);
            await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
        }

        if (shouldScrollToBottom)
        {
            shouldScrollToBottom = false;
            if (jsModule is not null)
            {
                await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
            }
        }
    }

    private async Task HandleSend(string content)
    {
        shouldScrollToBottom = true;
        await OnSendMessage.InvokeAsync(content);
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (HasMoreMessages && !IsLoading)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    public async ValueTask DisposeAsync()
    {
        dotNetRef?.Dispose();
        if (jsModule is not null)
        {
            await jsModule.DisposeAsync();
        }
    }
}

export function registerScrollHandler(element, dotNetRef) {
    if (!element) return;

    let ticking = false;
    element.addEventListener('scroll', () => {
        if (!ticking) {
            ticking = true;
            requestAnimationFrame(() => {
                if (element.scrollTop < 50) {
                    dotNetRef.invokeMethodAsync('OnScrolledToTop');
                }
                ticking = false;
            });
        }
    });
}

export function scrollToBottom(element) {
    if (!element) return;
    element.scrollTop = element.scrollHeight;
}

