@page "/chat"
@layout sv_f48e9de4ebad459591c2680a1b0f36c4.Components.Layout.ChatLayout
@rendermode InteractiveServer
@using sv_f48e9de4ebad459591c2680a1b0f36c4.Services
@using sv_f48e9de4ebad459591c2680a1b0f36c4.Components.Chat
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <ChannelSidebar Channels="channels"
                    SelectedChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="main-content @(activeThreadRootId.HasValue ? "" : "expanded")">
        @if (selectedChannel is not null)
        {
            <MessageArea ChannelName="@selectedChannel.Name"
                         ChannelDescription="@selectedChannel.Description"
                         Messages="messages"
                         ThreadSummaries="threadSummaries"
                         HasMoreMessages="hasMoreMessages"
                         IsLoading="isLoadingMore"
                         OnLoadMore="LoadMoreMessages"
                         OnSendMessage="SendMessage"
                         OnOpenThread="OpenThread"
                         OnReact="AddReaction" />
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (activeThreadRootId.HasValue && threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadMessages"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply"
                     OnReact="AddReaction" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private int selectedChannelId;
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private bool hasMoreMessages = true;
    private bool isLoadingMore;

    private int? activeThreadRootId;
    private Message? threadRootMessage;
    private List<Message> threadMessages = [];

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        threadSummaries = new();
        hasMoreMessages = true;
        CloseThread();

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messages = loaded;
        hasMoreMessages = loaded.Count >= PageSize;
        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channelId);
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || !hasMoreMessages) return;
        isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        messages.InsertRange(0, older);
        hasMoreMessages = older.Count >= PageSize;
        BuildThreadSummaries();

        isLoadingMore = false;
    }

    private void BuildThreadSummaries()
    {
        var replies = messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in replies)
        {
            threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        activeThreadRootId = rootMessageId;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        threadMessages = await ChatService.GetThreadAsync(rootMessageId);

        // Update the thread summary with accurate data
        if (threadMessages.Count > 0)
        {
            threadSummaries[rootMessageId] = new ThreadSummary(
                rootMessageId,
                threadMessages.Count,
                threadMessages.Max(m => m.SentAt));
        }
    }

    private void CloseThread()
    {
        activeThreadRootId = null;
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (!activeThreadRootId.HasValue) return;

        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, activeThreadRootId.Value);
        threadMessages.Add(reply);

        threadSummaries[activeThreadRootId.Value] = new ThreadSummary(
            activeThreadRootId.Value,
            threadMessages.Count,
            reply.SentAt);
    }

    private async Task AddReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        // Refresh messages to reflect updated reactions
