@using sv_f48e9de4ebad459591c2680a1b0f36c4.Services

<div class="thread-panel">
    <div class="thread-header">
        <h5>Thread</h5>
        <button class="btn-close btn-close-white" aria-label="Close" @onclick="OnClose"></button>
    </div>
    <div class="thread-root-message">
        <span class="root-author">@RootMessage.Author</span>
        <div class="root-content">@RootMessage.Content</div>
    </div>
    @if (Replies.Count > 0)
    {
        <div class="reply-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>
    }
    <div class="thread-replies">
        @foreach (var reply in Replies)
        {
            <MessageBubble Message="reply"
                           OnOpenThread="@((_) => { })"
                           OnReact="OnReact" />
        }
    </div>
    <MessageInput Placeholder="Reply…"
                  ButtonText="Reply"
                  OnSubmit="OnReply" />
</div>

@code {
    [Parameter, EditorRequired] public Message RootMessage { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
}

.thread-panel {
    flex: 0 0 25%;
    background-color: #36393f;
    border-left: 1px solid #2c2f33;
    display: flex;
    flex-direction: column;
    color: #dcddde;
    min-width: 0;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 16px;
    border-bottom: 1px solid #2c2f33;
    flex-shrink: 0;
}

.thread-header h5 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

.thread-root-message {
    padding: 12px 16px;
    background-color: #2f3136;
    border-bottom: 1px solid #2c2f33;
    flex-shrink: 0;
}

.root-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.88em;
}

.root-content {
    margin-top: 4px;
    font-size: 0.88em;
    line-height: 1.4;
}

.reply-divider {
    display: flex;
    align-items: center;
    padding: 6px 16px;
    flex-shrink: 0;
}

.reply-divider::before,
.reply-divider::after {
    content: "";
    flex: 1;
    border-bottom: 1px solid #4f545c;
}

.reply-divider span {
    padding: 0 10px;
    font-size: 0.75em;
    color: #72767d;
    white-space: nowrap;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 12px;
}

